import 'reflect-metadata';
import { config as loadDotenv } from 'dotenv';
import { DataSource } from 'typeorm';

/**
 * Standalone DataSource used only by the TypeORM CLI (`npm run migration:*`).
 * It runs outside the Nest DI container, before any application process bootstraps,
 * so it loads `.env` directly instead of going through ConfigurationModule.
 */
loadDotenv();

export const AppDataSource = new DataSource({
  type: 'postgres',
  host: process.env.DATABASE_HOST ?? 'localhost',
  port: Number(process.env.DATABASE_PORT ?? 5432),
  username: process.env.DATABASE_USERNAME ?? '',
  password: process.env.DATABASE_PASSWORD ?? '',
  database: process.env.DATABASE_NAME ?? '',
  ssl: process.env.DATABASE_SSL === 'true' ? { rejectUnauthorized: false } : false,
  synchronize: false,
  entities: ['libs/modules/**/*.orm-entity.ts', 'libs/platform/**/*.orm-entity.ts'],
  migrations: ['libs/platform/database/src/migrations/*.ts'],
  migrationsTableName: 'migrations',
});

